import json
import os
import re
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_sql_file(file_path):
    """Parse SQL file and extract table data."""
    data = []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find all INSERT statements
    insert_pattern = r'INSERT INTO \w+ \([^)]+\) VALUES\s*\(([^)]+)\)'
    matches = re.findall(insert_pattern, content, re.IGNORECASE | re.DOTALL)

    for match in matches:
        # Split by comma but handle quoted strings and NULL
        values = []
        current = ''
        in_quotes = False
        quote_char = None

        for char in match.strip():
            if char in ("'", '"') and not in_quotes:
                in_quotes = True
                quote_char = char
                current += char
            elif char == quote_char and in_quotes:
                in_quotes = False
                current += char
            elif char == ',' and not in_quotes:
                values.append(current.strip())
                current = ''
            else:
                current += char

        if current:
            values.append(current.strip())

        # Clean values
        cleaned_values = []
        for v in values:
            if v.upper() == 'NULL':
                cleaned_values.append(None)
            elif v.startswith("'") and v.endswith("'"):
                cleaned_values.append(v[1:-1])
            elif v.startswith('"') and v.endswith('"'):
                cleaned_values.append(v[1:-1])
            else:
                # Try to parse as number
                try:
                    if '.' in v:
                        cleaned_values.append(float(v))
                    else:
                        cleaned_values.append(int(v))
                except ValueError:
                    cleaned_values.append(v)

        data.append(cleaned_values)

    return data

def get_table_schema(file_path):
    """Extract column names from CREATE TABLE statement."""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find CREATE TABLE statement
    create_pattern = r'CREATE TABLE \w+ \(([^)]+)\)'
    match = re.search(create_pattern, content, re.IGNORECASE | re.DOTALL)

    if not match:
        return []

    columns_section = match.group(1)
    columns = []

    # Parse column definitions
    for line in columns_section.split(','):
        line = line.strip()
        if line:
            # Extract column name (first word before space)
            col_name = line.split()[0]
            columns.append(col_name)

    return columns

def load_document_data(doc_name, directory):
    """Load data from a document file."""
    file_path = os.path.join(directory, f"{doc_name}.sql")
    if not os.path.exists(file_path):
        return []

    columns = get_table_schema(file_path)
    rows = parse_sql_file(file_path)

    data = []
    for row in rows:
        if len(row) != len(columns):
            continue
        record = {}
        for i, col in enumerate(columns):
            record[col] = row[i]
        data.append(record)

    return data

def epoch_day_to_date(epd):
    """Convert epoch day to YYYY-MM-DD string."""
    if epd is None:
        return None
    base_date = datetime(1970, 1, 1)
    target_date = base_date + timedelta(days=int(epd))
    return target_date.strftime('%Y-%m-%d')

def dan_to_kn(dan):
    """Convert decanewtons to kilonewtons."""
    if dan is None:
        return None
    return float(dan) / 100.0

def get_calibration_date(cmp_code, calibration_log_data):
    """Get calibration date for a component from calibration_log."""
    for record in calibration_log_data:
        if record.get('cmp_code') == cmp_code:
            epd = record.get('rig_cal_epd')
            if epd is not None:
                return epoch_day_to_date(epd), "calibration_log"
    return None, None

def get_test_date(cmp_code, test_reports_data, lab_certificates_data):
    """Get test date for a component, preferring test_reports."""
    # First try test_reports
    for record in test_reports_data:
        if record.get('cmp_code') == cmp_code:
            epd = record.get('inhouse_break_epd')
            if epd is not None:
                return epoch_day_to_date(epd), "test_reports"

    # Fallback to lab_certificates
    for record in lab_certificates_data:
        if record.get('cmp_code') == cmp_code:
            epd = record.get('lab_break_epd')
            if epd is not None:
                return epoch_day_to_date(epd), "lab_certificates"

    return None, None

def get_measured_load(cmp_code, lab_certificates_data, test_reports_data):
    """Get measured load in kN, preferring lab_certificates."""
    # First try lab_certificates
    lab_values = []
    for record in lab_certificates_data:
        if record.get('cmp_code') == cmp_code:
            dan = record.get('lab_break_dan')
            if dan is not None:
                lab_values.append(dan)

    if lab_values:
        # Check for conflicts
        if len(set(lab_values)) > 1:
            return "CONFLICT", "lab_certificates"
        return dan_to_kn(lab_values[0]), "lab_certificates"

    # Fallback to test_reports
    test_values = []
    for record in test_reports_data:
        if record.get('cmp_code') == cmp_code:
            dan = record.get('inhouse_break_dan')
            if dan is not None:
                test_values.append(dan)

    if test_values:
        # Check for conflicts
        if len(set(test_values)) > 1:
            return "CONFLICT", "test_reports"
        return dan_to_kn(test_values[0]), "test_reports"

    return "ABSENT", None

def get_specified_minimum(cmp_code, spec_sheets_data):
    """Get specified minimum load in kN from spec_sheets."""
    values = []
    for record in spec_sheets_data:
        if record.get('cmp_code') == cmp_code:
            dan = record.get('floor_force_dan')
            if dan is not None:
                values.append(dan)

    if not values:
        return "ABSENT", None

    # Check for conflicts
    if len(set(values)) > 1:
        return "CONFLICT", "spec_sheets"

    return dan_to_kn(values[0]), "spec_sheets"

def process_pair(pair_id, rule_name, cmp_code, all_data):
    """Process a single pair and return its facts."""
    result = {}

    if rule_name == "ea.calibration_current":
        # Get calibration date
