        else:
            result['test date'] = [test_date, test_doc]

    elif rule_name == "ea.load_with_margin":
        # Get measured load
        measured_load, measured_doc = get_measured_load(cmp_code, all_data['lab_certificates'], all_data['test_reports'])
        if measured_load == "ABSENT":
            result['measured load'] = "ABSENT"
        elif measured_load == "CONFLICT":
            result['measured load'] = "CONFLICT"
        else:
            # Format as decimal string
            result['measured load'] = [f"{measured_load:.2f}", measured_doc]

        # Get specified minimum
        spec_min, spec_doc = get_specified_minimum(cmp_code, all_data['spec_sheets'])
        if spec_min == "ABSENT":
