import json
import os
import sys
from pathlib import Path
from datetime import datetime
from collections import defaultdict

def parse_edi_file(file_path):
    """Parse EDI file and extract records by BP (buyer catalog key)."""
    records = defaultdict(list)
    current_record = {}
    in_loop = False
    bp_key = None

    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue

            segments = line.split('~')
            for segment in segments:
                if not segment:
                    continue

                fields = segment.split('*')
                segment_id = fields[0] if fields else ''

                # Start of loop
                if segment_id == 'LX':
                    if in_loop and bp_key and current_record:
                        records[bp_key].append(current_record.copy())
                    in_loop = True
                    current_record = {}
                    bp_key = None

                # Buyer catalog key
                elif segment_id == 'LIN' and len(fields) >= 4:
                    if fields[3] == 'BP' and len(fields) > 4:
                        bp_key = fields[4]
                        current_record['BP'] = bp_key

                # Supplier
                elif segment_id == 'N1' and len(fields) >= 3:
                    if fields[1] == 'SU':
                        current_record['SUPPLIER'] = fields[2]

                # Drawing revision
                elif segment_id == 'REF' and len(fields) >= 3:
                    if fields[1] == 'DR':
                        current_record['DR'] = fields[2]

                # Dates
                elif segment_id == 'DTP' and len(fields) >= 4:
                    qualifier = fields[1]
                    date_str = fields[3]
                    if len(date_str) == 8:  # CCYYMMDD
                        try:
                            date_obj = datetime.strptime(date_str, '%Y%m%d').date()
                            if qualifier == '300':  # calibration date
                                current_record['CALIBRATION_DATE'] = date_obj
                            elif qualifier == '301':  # in-house test date
                                current_record['TEST_DATE_301'] = date_obj
                            elif qualifier == '302':  # lab test date
                                current_record['TEST_DATE_302'] = date_obj
                            elif qualifier == '690':  # test booked
                                current_record['TEST_BOOKED'] = date_obj
                        except ValueError:
                            pass

                # Measurements
                elif segment_id == 'MEA' and len(fields) >= 6:
                    if fields[1] == 'TE':
                        qualifier = fields[2]
                        value = fields[3]
                        unit = fields[4]

                        try:
                            num_value = float(value)
                            # Convert to kN if needed
                            if unit == 'NT':
                                num_value = num_value / 1000.0
                            elif unit == 'KN':
                                pass  # already in kN
                            else:
                                continue

                            if qualifier == 'UFL':  # ultimate force from lab
                                current_record['MEASURED_LOAD_UFL'] = num_value
                            elif qualifier == 'UFH':  # ultimate force in-house
                                current_record['MEASURED_LOAD_UFH'] = num_value
                            elif qualifier == 'UFM':  # minimum acceptable force
                                current_record['SPECIFIED_MINIMUM'] = num_value
                            elif qualifier == 'DUF':  # design ultimate force
                                current_record['DESIGN_ULTIMATE'] = num_value
                        except ValueError:
                            pass

        # Add last record
        if in_loop and bp_key and current_record:
            records[bp_key].append(current_record.copy())

    return records

def extract_facts(directory):
    """Extract facts from all EDI files in directory."""
    files = {
        'calibration_log': 'calibration_log.edi',
        'lab_certificates': 'lab_certificates.edi',
        'parts': 'parts.edi',
        'spec_sheets': 'spec_sheets.edi',
        'test_reports': 'test_reports.edi'
    }

    data = {}
    for name, filename in files.items():
        filepath = Path(directory) / filename
        if filepath.exists():
            data[name] = parse_edi_file(filepath)
        else:
            data[name] = {}

    return data

def get_calibration_date(data, part_id):
    """Get calibration date from calibration_log."""
    if part_id in data['calibration_log']:
        for record in data['calibration_log'][part_id]:
            if 'CALIBRATION_DATE' in record:
                return record['CALIBRATION_DATE'].strftime('%Y-%m-%d'), 'calibration_log'
    return None, None

def get_test_date(data, part_id):
    """Get test date from test_reports first, then lab_certificates."""
    # Check test_reports
    if part_id in data['test_reports']:
        dates = []
        for record in data['test_reports'][part_id]:
            if 'TEST_DATE_301' in record:
                dates.append((record['TEST_DATE_301'].strftime('%Y-%m-%d'), 'test_reports'))
        if dates:
            # Return the first one found
            return dates[0]

    # Check lab_certificates
    if part_id in data['lab_certificates']:
        dates = []
        for record in data['lab_certificates'][part_id]:
            if 'TEST_DATE_302' in record:
                dates.append((record['TEST_DATE_302'].strftime('%Y-%m-%d'), 'lab_certificates'))
        if dates:
            return dates[0]

    return None, None

def get_measured_load(data, part_id):
    """Get measured load from lab_certificates first, then test_reports."""
    # Check lab_certificates
    if part_id in data['lab_certificates']:
        loads = []
        for record in data['lab_certificates'][part_id]:
            if 'MEASURED_LOAD_UFL' in record:
                loads.append((record['MEASURED_LOAD_UFL'], 'lab_certificates'))
        if loads:
            # Check for conflicts
            if len(set(load[0] for load in loads)) > 1:
                return "CONFLICT", None
            return f"{loads[0][0]:g}", loads[0][1]

    # Check test_reports
    if part_id in data['test_reports']:
        loads = []
        for record in data['test_reports'][part_id]:
            if 'MEASURED_LOAD_UFH' in record:
                loads.append((record['MEASURED_LOAD_UFH'], 'test_reports'))
        if loads:
            # Check for conflicts
            if len(set(load[0] for load in loads)) > 1:
                return "CONFLICT", None
            return f"{loads[0][0]:g}", loads[0][1]

    return None, None

def get_specified_minimum(data, part_id):
    """Get specified minimum from spec_sheets."""
    if part_id in data['spec_sheets']:
        values = []
        for record in data['spec_sheets'][part_id]:
            if 'SPECIFIED_MINIMUM' in record:
                values.append((record['SPECIFIED_MINIMUM'], 'spec_sheets'))
        if values:
            # Check for conflicts
            if len(set(value[0] for value in values)) > 1:
                return "CONFLICT", None
            return f"{values[0][0]:g}", values[0][1]
    return None, None

def main():
    if len(sys.argv) != 2:
        print("Usage: python extract_facts.py <directory_path>")
        sys.exit(1)

    directory = sys.argv[1]
    data = extract_facts(directory)

    # All part IDs from the pairs list
    part_ids = [f"P-401{i:02d}" for i in range(1, 17)]

    result = {}

    # Process calibration_current pairs
    for part_id in part_ids:
        pair_id = f"ea.calibration_current::{part_id}"

        calibration_date, cal_doc = get_calibration_date(data, part_id)
        test_date, test_doc = get_test_date(data, part_id)

        facts = {}

        if calibration_date is None:
            facts['calibration date'] = "ABSENT"
        else:
            facts['calibration date'] = [calibration_date, cal_doc]

        if test_date is None:
            facts['test date'] = "ABSENT"
        else:
            facts['test date'] = [test_date, test_doc]

        result[pair_id] = facts

    # Process load_with_margin pairs
    for part_id in part_ids:
        pair_id = f"ea.load_with_margin::{part_id}"

        measured_load, load_doc = get_measured_load(data, part_id)
        specified_minimum, spec_doc = get_specified_minimum(data, part_id)

        facts = {}

        if measured_load is None:
            facts['measured load'] = "ABSENT"
        elif measured_load == "CONFLICT":
            facts['measured load'] = "CONFLICT"
        else:
            facts['measured load'] = [measured_load, load_doc]

        if specified_minimum is None:
            facts['specified minimum'] = "ABSENT"
        elif specified_minimum == "CONFLICT":
            facts['specified minimum'] = "CONFLICT"
        else:
            facts['specified minimum'] = [specified_minimum, spec_doc]

        result[pair_id] = facts

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
