import json
import os
import re
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_edi_file(file_path: Path) -> List[Dict]:
    """Parse an EDI file and extract records for each LX loop."""
    records = []
    current_record = {}
    in_loop = False

    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue

            # Start of a new loop
            if line.startswith('LX'):
                if current_record:
                    records.append(current_record)
                current_record = {}
                in_loop = True
                # Parse LX number if needed
                parts = line.split('*')
                if len(parts) > 1:
                    current_record['LX'] = parts[1]
                continue

            if not in_loop:
                continue

            # Parse segments
            if line.startswith('LIN'):
                parts = line.split('*')
                # LIN**BP*P-40201 format
                if len(parts) >= 4 and parts[2] == 'BP':
                    current_record['BP'] = parts[3]  # Buyer catalog key
            elif line.startswith('N1'):
                parts = line.split('*')
                if len(parts) >= 3 and parts[1] == 'SU':
                    current_record['SU'] = parts[2]  # Supplier
            elif line.startswith('REF'):
                parts = line.split('*')
                if len(parts) >= 3:
                    qual = parts[1]
                    value = parts[2]
                    if qual == 'DR':
                        current_record['DR'] = value  # Drawing revision
                    elif qual == 'ZZ':
                        current_record['ZZ'] = value  # Source system token
                    elif qual == 'QAD':
                        current_record['QAD'] = value  # Quality release decision
            elif line.startswith('DTP'):
                parts = line.split('*')
                if len(parts) >= 4:
                    qual = parts[1]
                    date_str = parts[3]
                    # Convert CCYYMMDD to YYYY-MM-DD
                    if len(date_str) == 8:
                        date_formatted = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
                        if qual == '300':
                            current_record['CALIBRATION_DATE'] = date_formatted
                        elif qual == '301':
                            current_record['TEST_DATE_INHOUSE'] = date_formatted
                        elif qual == '302':
                            current_record['TEST_DATE_LAB'] = date_formatted
                        elif qual == '690':
                            current_record['TEST_BOOKED'] = date_formatted
                        elif qual == '097':
                            current_record['CREATED_DATE'] = date_formatted
            elif line.startswith('MEA'):
                parts = line.split('*')
                if len(parts) >= 6:
                    qual1 = parts[1]
                    qual2 = parts[2]
                    qual3 = parts[3]
                    value = parts[4]
                    unit = parts[5]

                    if qual1 == 'TE':
                        if qual2 == 'UFL':
                            current_record['UFL'] = (value, unit)  # Ultimate force lab
                        elif qual2 == 'UFH':
                            current_record['UFH'] = (value, unit)  # Ultimate force in-house
                        elif qual2 == 'DUF':
                            current_record['DUF'] = (value, unit)  # Design ultimate force
                        elif qual2 == 'UFM':
                            current_record['UFM'] = (value, unit)  # Minimum ultimate force

    # Add the last record
    if current_record:
        records.append(current_record)

    return records

def convert_to_kilonewtons(value: str, unit: str) -> str:
    """Convert force values to kilonewtons."""
    try:
        num = float(value)
        if unit == 'NT':
            # Convert newtons to kilonewtons
            result = num / 1000.0
        elif unit == 'KN':
            result = num
        else:
            # Unknown unit, return as is
            return value
        # Format with up to 3 decimal places, remove trailing zeros
        formatted = f"{result:.3f}".rstrip('0').rstrip('.')
        return formatted if formatted else "0"
    except (ValueError, TypeError):
        return value

def extract_facts_for_pair(pair_id: str, records_by_source: Dict[str, List[Dict]]) -> Dict:
    """Extract facts for a specific pair based on decision rules."""
    rule_type, part_id = pair_id.split('::')
    result = {}

    if rule_type == 'ea.calibration_current':
        # Fact: calibration date
        cal_records = records_by_source.get('calibration_log', [])
        cal_date = None
        cal_doc = None

        for record in cal_records:
            if record.get('BP') == part_id and 'CALIBRATION_DATE' in record:
                if cal_date is None:
                    cal_date = record['CALIBRATION_DATE']
                    cal_doc = 'calibration_log'
                elif cal_date != record['CALIBRATION_DATE']:
                    # Conflict in calibration dates
                    result['calibration date'] = 'CONFLICT'
                    break

        if 'calibration date' not in result:
            if cal_date:
                result['calibration date'] = [cal_date, cal_doc]
            else:
                result['calibration date'] = 'ABSENT'

