def parse_date(date_str: str) -> Optional[datetime]:
    """Parse various date formats from the text."""
    if not date_str:
        return None

    # Remove ordinal suffixes (st, nd, rd, th) and commas
    date_str = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)
    date_str = date_str.replace(',', '')

    # Try multiple date formats
    formats = [
        "%d %b %Y",  # 11th Jan 2026 -> 11 Jan 2026
        "%d %B %Y",  # January 11 2026
        "%B %d %Y",  # January 11th 2026
        "%b %d %Y",  # Jan 11 2026
        "%Y-%m-%d",  # Already formatted
        "%d/%m/%Y",
        "%m/%d/%Y",
    ]

    for fmt in formats:
        try:
            return datetime.strptime(date_str.strip(), fmt)
        except ValueError:
            continue

    # Try formats with month name and day without year (shouldn't happen here)
    return None

def extract_calibration_date(text: str, entity: str) -> Optional[Tuple[str, str]]:
    """Extract calibration date from calibration_log for a specific entity."""
    # Split into messages
    messages = re.split(r'={5,}', text)

    for msg in messages:
        if not msg.strip():
            continue

        # Check if this message is about our entity
        if f'P-{entity}' not in msg and f'P-{entity}' not in msg.replace('-', ''):
            # Try pattern like P-40201 in subject
            if not re.search(rf'\bP-{entity}\b', msg):
                continue

        # Look for date patterns
        date_patterns = [
            r'calibrated on\s+([^\.]+)\.',
            r'calibration sticker says\s+([^\.]+)\.',
            r'calibrated on\s+([^,]+),',
            r'calibrated on\s+([^\.]+?)\s*(?:\.|$)',
        ]

        for pattern in date_patterns:
            match = re.search(pattern, msg, re.IGNORECASE)
            if match:
                date_str = match.group(1).strip()
                # Check for "I can't find" or similar
                if 'can\'t find' in date_str.lower() or 'isn\'t recorded' in date_str.lower():
                    return None

                date_obj = parse_date(date_str)
                if date_obj:
                    return (date_obj.strftime("%Y-%m-%d"), "calibration_log")

    return None

def extract_test_date_from_test_reports(text: str, entity: str) -> Optional[Tuple[str, str]]:
    """Extract test date from test_reports for a specific entity."""
    messages = re.split(r'={5,}', text)

    for msg in messages:
        if not msg.strip():
            continue

        if not re.search(rf'\bP-{entity}\b', msg):
            continue

        # Look for test date patterns
        date_patterns = [
            r'ran on\s+([^\.]+)\.',
            r'broke it on the frame on\s+([^\.]+)\.',
            r'test day isn\'t recorded',
            r'test ran on\s+([^\.]+)\.',
            r'test on\s+([^\.]+)\.',
        ]

        for pattern in date_patterns:
            match = re.search(pattern, msg, re.IGNORECASE)
            if match:
                date_str = match.group(1).strip() if len(match.groups()) > 0 else ""
                if 'isn\'t recorded' in date_str.lower():
                    return None

                if date_str:
                    date_obj = parse_date(date_str)
                    if date_obj:
                        return (date_obj.strftime("%Y-%m-%d"), "test_reports")

