import json
import os
import sys
from pathlib import Path
from datetime import datetime, timedelta
import re

def parse_iso_week_date(date_str):
    """Parse ISO week date YYYY-Www-D to datetime.date."""
    if date_str == "~":
        return None
    # Format: 2026-W28-2
    match = re.match(r"(\d{4})-W(\d{2})-(\d)", date_str)
    if not match:
        raise ValueError(f"Invalid ISO week date: {date_str}")
    year, week, day = map(int, match.groups())
    # First Thursday of year is in week 1 per ISO
    # Use simple calculation: get Jan 4 (which is always in week 1)
    jan4 = datetime(year, 1, 4).date()
    # Monday of week 1
    start = jan4 - timedelta(days=jan4.weekday())  # Monday
    # Add weeks and days (day 1=Monday, 7=Sunday)
    result = start + timedelta(weeks=week-1, days=day-1)
    return result

def load_tsv_file(filepath):
    """Load a TSV file with cross-tab orientation.
    Returns dict: {component_key: {attribute: value}}"""
    data = {}
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = [line.rstrip('\n') for line in f if not line.startswith('#')]
    if not lines:
        return data
    headers = lines[0].split('\t')
    # First column is 'attribute'
    # Other columns are rec.01, rec.02, etc.
    # Build mapping from component.key to column index
    component_key_row = None
    for i, line in enumerate(lines[1:], 1):
        parts = line.split('\t')
        if parts[0] == 'component.key':
            component_key_row = parts
            break
    if not component_key_row:
        return data
    # For each column (record), collect its component key
    # Skip first column (attribute)
    for col_idx in range(1, len(headers)):
        component_key = component_key_row[col_idx]
        if component_key == "~":
            continue
        data[component_key] = {}
    # Now fill attributes
    for line in lines[1:]:
        parts = line.split('\t')
        attribute = parts[0]
        for col_idx in range(1, len(headers)):
            if col_idx >= len(parts):
                break
            component_key = component_key_row[col_idx]
            if component_key == "~":
                continue
            value = parts[col_idx]
            if value != "~":
                data[component_key][attribute] = value
    return data

def get_calibration_date(component_key, data):
    """Get calibration date from calibration_log."""
    if component_key not in data:
        return None
    rec = data[component_key]
    if 'rig.cal.wk' not in rec:
        return None
    return parse_iso_week_date(rec['rig.cal.wk'])

def get_test_date(component_key, test_reports_data, lab_certificates_data):
    """Get test date: first from test_reports, fallback to lab_certificates."""
    # Try test_reports first
    if component_key in test_reports_data:
        rec = test_reports_data[component_key]
        if 'inhouse.break.wk' in rec:
            date = parse_iso_week_date(rec['inhouse.break.wk'])
            if date is not None:
                return date, 'test_reports.tsv'
    # Fallback to lab_certificates
    if component_key in lab_certificates_data:
        rec = lab_certificates_data[component_key]
        if 'lab.break.wk' in rec:
            date = parse_iso_week_date(rec['lab.break.wk'])
            if date is not None:
                return date, 'lab_certificates.tsv'
    return None, None

def get_measured_load(component_key, lab_certificates_data, test_reports_data):
    """Get measured load: first from lab_certificates, fallback to test_reports."""
    # Try lab_certificates first
    if component_key in lab_certificates_data:
        rec = lab_certificates_data[component_key]
        if 'lab.break.kn' in rec:
            try:
                value = float(rec['lab.break.kn'])
                return value, 'lab_certificates.tsv'
            except ValueError:
                pass
    # Fallback to test_reports
    if component_key in test_reports_data:
        rec = test_reports_data[component_key]
        if 'inhouse.break.kn' in rec:
            try:
                value = float(rec['inhouse.break.kn'])
                return value, 'test_reports.tsv'
            except ValueError:
                pass
    return None, None

def get_specified_minimum(component_key, spec_sheets_data):
    """Get specified minimum from spec_sheets."""
    if component_key not in spec_sheets_data:
        return None, None
    rec = spec_sheets_data[component_key]
    if 'floor.force.kn' not in rec:
        return None, None
    try:
        value = float(rec['floor.force.kn'])
        return value, 'spec_sheets.tsv'
    except ValueError:
        return None, None

def handle_conflict(values_with_sources):
    """Check if there are conflicting values for the same component.
    values_with_sources: list of (value, source) tuples.
    Returns (value, source) or (None, 'CONFLICT') if conflict."""
    if not values_with_sources:
        return None, None
    # Filter out None values
    valid = [(v, s) for v, s in values_with_sources if v is not None]
    if not valid:
        return None, None
    # Check if all values are the same
    first_val, first_src = valid[0]
    for val, src in valid[1:]:
        if val != first_val:
            return None, 'CONFLICT'
    # All same, return first
    return first_val, first_src

def main(directory_path):
    # Load all data files
    base_path = Path(directory_path)

    calibration_log_data = load_tsv_file(base_path / 'calibration_log.tsv')
    lab_certificates_data = load_tsv_file(base_path / 'lab_certificates.tsv')
    parts_data = load_tsv_file(base_path / 'parts.tsv')
    spec_sheets_data = load_tsv_file(base_path / 'spec_sheets.tsv')
    test_reports_data = load_tsv_file(base_path / 'test_reports.tsv')

    # All component keys from the pairs
    component_keys = [f"P-404{i:02d}" for i in range(1, 17)]

    result = {}

    # Process ea.calibration_current pairs
    for key in component_keys:
        pair_id = f"ea.calibration_current::{key}"
        pair_result = {}

        # Fact: calibration date
        cal_date = get_calibration_date(key, calibration_log_data)
        if cal_date is None:
            pair_result['calibration date'] = "ABSENT"
        else:
            pair_result['calibration date'] = [cal_date.isoformat(), 'calibration_log.tsv']

        # Fact: test date
        test_date, test_source = get_test_date(key, test_reports_data, lab_certificates_data)
        if test_date is None:
