import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse MM/DD/YYYY date string to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%m/%d/%Y").date()
    except ValueError:
        return None

def parse_force(value_str, unit):
    """Parse force value and convert to kN if needed."""
    if not value_str or value_str.strip() == "":
        return None
    try:
        value = float(value_str.strip())
        if unit == "N":
            return value / 1000  # Convert N to kN
        elif unit == "KN":
            return value
        else:
            return None
    except ValueError:
        return None

def read_delimited_file(filepath):
    """Read a delimited file with '#' comments and return list of dicts."""
    data = []
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Find header (first non-comment line)
    header = None
    for line in lines:
        if not line.startswith('#'):
            header = line.strip().split('|')
            break

    if not header:
        return data

    # Process data lines
    for line in lines:
        if line.startswith('#') or line.strip() == '':
            continue
        if line.strip().split('|')[0] == header[0]:  # Skip header line
            continue

        values = line.strip().split('|')
        if len(values) != len(header):
            continue

        record = {}
        for i, field in enumerate(header):
            record[field] = values[i] if i < len(values) else ""
        data.append(record)

    return data

def get_calibration_date(calibration_logs, component_key):
    """Get calibration date for a component from calibration_log."""
    for record in calibration_logs:
        if record.get('COMPONENT_CATALOG_KEY') == component_key:
            date_str = record.get('LOAD_FRAME_CAL_DAY')
            return parse_date(date_str)
    return None

def get_test_date(test_reports, lab_certificates, component_key):
    """Get test date from test_reports first, then lab_certificates."""
    # Try test_reports first
    for record in test_reports:
        if record.get('COMPONENT_CATALOG_KEY') == component_key:
            date_str = record.get('INTERNAL_TRIAL_DAY')
            date = parse_date(date_str)
            if date is not None:
                return date, 'test_reports'

    # Fallback to lab_certificates
    for record in lab_certificates:
        if record.get('COMPONENT_CATALOG_KEY') == component_key:
            date_str = record.get('ACCREDITED_TRIAL_DAY')
            date = parse_date(date_str)
            if date is not None:
                return date, 'lab_certificates'

    return None, None

def get_measured_load(lab_certificates, test_reports, component_key):
    """Get measured load in kN from lab_certificates first, then test_reports."""
    # Try lab_certificates first
    for record in lab_certificates:
        if record.get('COMPONENT_CATALOG_KEY') == component_key:
            force_str = record.get('ACCREDITED_ULTIMATE_FORCE')
            unit = record.get('ACCREDITED_ULTIMATE_FORCE_UOM')
            if force_str and unit:
                load = parse_force(force_str, unit)
                if load is not None:
                    return load, 'lab_certificates'

    # Fallback to test_reports
    for record in test_reports:
        if record.get('COMPONENT_CATALOG_KEY') == component_key:
            force_str = record.get('INTERNAL_ULTIMATE_FORCE')
            unit = record.get('INTERNAL_ULTIMATE_FORCE_UOM')
            if force_str and unit:
                load = parse_force(force_str, unit)
                if load is not None:
                    return load, 'test_reports'

    return None, None

def get_specified_minimum(spec_sheets, component_key):
    """Get specified minimum load in kN from spec_sheets."""
    for record in spec_sheets:
        if record.get('COMPONENT_CATALOG_KEY') == component_key:
            force_str = record.get('REQUIRED_ULTIMATE_FORCE')
            unit = record.get('REQUIRED_ULTIMATE_FORCE_UOM')
            if force_str and unit:
                load = parse_force(force_str, unit)
                if load is not None:
                    return load, 'spec_sheets'
    return None, None

def format_value(value, document):
    """Format value according to output specification."""
    if value is None:
        return "ABSENT"
    elif isinstance(value, (int, float)):
        # Format decimal string without unnecessary trailing zeros
        if isinstance(value, float) and value.is_integer():
            return [f"{int(value)}", document]
        else:
            return [f"{value}", document]
    elif isinstance(value, datetime.date):
        return [value.strftime("%Y-%m-%d"), document]
    else:
        return [str(value), document]

def check_conflict(values):
    """Check if there are conflicting values for the same entity."""
    if not values:
        return False
    # Compare all values, ignoring document source
    first_val = values[0][0] if isinstance(values[0], list) else values[0]
    for val in values[1:]:
        current_val = val[0] if isinstance(val, list) else val
        if current_val != first_val:
            return True
    return False

def resolve_fact(values):
    """Resolve a fact from multiple potential values."""
    if not values:
        return "ABSENT"

    if check_conflict(values):
        return "CONFLICT"

    # Take the first value (should be from the primary document)
    return values[0]

def main(directory_path):
    # Read all data files
    base_path = Path(directory_path)

    calibration_logs = read_delimited_file(base_path / "calibration_log.txt")
    lab_certificates = read_delimited_file(base_path / "lab_certificates.txt")
    parts = read_delimited_file(base_path / "parts.txt")
    spec_sheets = read_delimited_file(base_path / "spec_sheets.txt")
    test_reports = read_delimited_file(base_path / "test_reports.txt")

    # Get all component keys from the pairs list
    component_keys = [f"P-404{i:02d}" for i in range(1, 17)]

    result = {}

    # Process calibration_current pairs
    for key in component_keys:
        pair_id = f"ea.calibration_current::{key}"

        # Get calibration date
        cal_date = get_calibration_date(calibration_logs, key)
        cal_values = []
        if cal_date is not None:
            cal_values.append(format_value(cal_date, "calibration_log"))

        # Get test date
        test_date, test_doc = get_test_date(test_reports, lab_certificates, key)
        test_values = []
        if test_date is not None:
            test_values.append(format_value(test_date, test_doc))

        result[pair_id] = {
            "calibration date": resolve_fact(cal_values),
            "test date": resolve_fact(test_values)
        }

    # Process load_with_margin pairs
    for key in component_keys:
        pair_id = f"ea.load_with_margin::{key}"

        # Get measured load
        measured_load, measured_doc = get_measured_load(lab_certificates, test_reports, key)
        measured_values = []
        if measured_load is not None:
            measured_values.append(format_value(measured_load, measured_doc))

        # Get specified minimum
        spec_min, spec_doc = get_specified_minimum(spec_sheets, key)
        spec_values = []
        if spec_min is not None:
            spec_values.append(format_value(spec_min, spec_doc))

        result[pair_id] = {
            "measured load": resolve_fact(measured_values),
            "specified minimum": resolve_fact(spec_values)
        }

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)

