import re
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_date(date_str: str) -> Optional[str]:
    """Parse a date string like 'Wed., June 24, 2026' to YYYY-MM-DD."""
    if not date_str or "left blank" in date_str:
        return None
    # Remove day of week and period
    date_str = re.sub(r'^[A-Za-z]+\.?,?\s*', '', date_str)
    # Parse month day, year
    try:
        dt = datetime.strptime(date_str.strip(), '%B %d, %Y')
    except ValueError:
        try:
            dt = datetime.strptime(date_str.strip(), '%b. %d, %Y')
        except ValueError:
            # Try with abbreviated month without period
            dt = datetime.strptime(date_str.strip(), '%b %d, %Y')
    return dt.strftime('%Y-%m-%d')

def parse_load(load_str: str) -> Optional[str]:
    """Parse a load string like '434 kN' to decimal string."""
    if not load_str or "left blank" in load_str:
        return None
    match = re.search(r'([\d\.]+)\s*kN', load_str)
    if match:
        return match.group(1)
    return None

def parse_html_file(filepath: Path) -> List[Dict]:
    """Parse an HTML file with sheets and extract data."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find all article elements with class "sheet"
    sheet_pattern = r'<article class="sheet"[^>]*>.*?</article>'
    sheets = re.findall(sheet_pattern, content, re.DOTALL)

    data = []
    for sheet in sheets:
        # Extract item code
        item_code_match = re.search(r'<strong>([^<]+)</strong>', sheet)
        if not item_code_match:
            continue
        item_code = item_code_match.group(1)

        # Extract all field rows
        rows = re.findall(r'<tr>.*?</tr>', sheet, re.DOTALL)
        fields = {}
        for row in rows:
            th_match = re.search(r'<th[^>]*>([^<]+)</th>', row)
            td_match = re.search(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)
            if th_match and td_match:
                field_name = th_match.group(1).strip()
                field_value = re.sub(r'<[^>]+>', '', td_match.group(1)).strip()
                fields[field_name] = field_value

        data.append({
            'item_code': item_code,
            'fields': fields
        })

    return data

def extract_facts_from_docs(directory: Path) -> Dict[str, Dict]:
    """Extract all facts from all documents in the directory."""
    files = {
        'calibration_log': 'calibration_log.html',
        'lab_certificates': 'lab_certificates.html',
        'parts': 'parts.html',
        'spec_sheets': 'spec_sheets.html',
        'test_reports': 'test_reports.html'
    }

    all_data = {}

    for doc_name, filename in files.items():
        filepath = directory / filename
        if not filepath.exists():
            continue

        sheets = parse_html_file(filepath)
        doc_data = {}

        for sheet in sheets:
            item_code = sheet['item_code']
            fields = sheet['fields']

            # Store raw field values
            doc_data[item_code] = fields

            # Also store parsed values for known fields
            parsed_values = {}

            # Map field names to fact names
            if doc_name == 'calibration_log':
                if 'Frame last calibrated' in fields:
                    parsed_values['calibration date'] = parse_date(fields['Frame last calibrated'])

            elif doc_name == 'lab_certificates':
                if 'Laboratory test performed' in fields:
                    parsed_values['test date'] = parse_date(fields['Laboratory test performed'])
                if 'Load at failure (lab certified)' in fields:
                    parsed_values['measured load'] = parse_load(fields['Load at failure (lab certified)'])

            elif doc_name == 'test_reports':
                if 'Break test performed' in fields:
                    parsed_values['test date'] = parse_date(fields['Break test performed'])
                if 'Load at failure (in-house)' in fields:
                    parsed_values['measured load'] = parse_load(fields['Load at failure (in-house)'])

            elif doc_name == 'spec_sheets':
                if 'Drawing minimum at failure' in fields:
                    parsed_values['specified minimum'] = parse_load(fields['Drawing minimum at failure'])

            # Store parsed values
            if parsed_values:
                if 'parsed' not in doc_data[item_code]:
                    doc_data[item_code]['parsed'] = {}
                doc_data[item_code]['parsed'].update(parsed_values)

        all_data[doc_name] = doc_data

    return all_data

def get_fact_value(doc_data: Dict, item_code: str, fact_name: str, 
                   doc_name: str) -> Tuple[Optional[str], Optional[str]]:
    """Get a fact value from a document for a specific item."""
    if item_code not in doc_data:
        return None, None

    item_data = doc_data[item_code]

    # Check if we have parsed value
    if 'parsed' in item_data and fact_name in item_data['parsed']:
        value = item_data['parsed'][fact_name]
        if value is not None:
            return value, doc_name

    return None, None

def resolve_fact(facts_data: Dict, item_code: str, fact_name: str, 
                 rule_def: Dict) -> Union[str, List[str]]:
    """Resolve a fact according to the decision rules."""

    if fact_name == 'calibration date':
        # Only from calibration_log
