        value, source = get_fact_value(facts_data[doc_name], item_code, fact_name, doc_name)
        if value is None:
            return "ABSENT"
        return [value, source]

    elif fact_name == 'test date':
        # First from test_reports, then lab_certificates
        for doc_name in ['test_reports', 'lab_certificates']:
            value, source = get_fact_value(facts_data[doc_name], item_code, fact_name, doc_name)
            if value is not None:
                return [value, source]
        return "ABSENT"

    elif fact_name == 'measured load':
        # First from lab_certificates, then test_reports
