            if value is not None:
                values[doc_name] = (value, source)

        if not values:
            return "ABSENT"

        # Check for conflicts
        if len(values) > 1:
            # Get all unique values
            unique_values = set(v[0] for v in values.values())
            if len(unique_values) > 1:
                return "CONFLICT"

        # Use the first in priority order
        for doc_name in ['lab_certificates', 'test_reports']:
            if doc_name in values:
