def parse_load(load_str: str) -> Optional[str]:
    """Parse load strings like '483 kN' to '483'."""
    if not load_str or "left blank" in load_str.lower():
        return None

    match = re.search(r'([\d.]+)\s*kN', load_str)
    if match:
        # Remove trailing .0 if integer
        value = match.group(1)
        if '.' in value:
            # Keep as decimal string
            return value.rstrip('0').rstrip('.') if '.' in value else value
        return value
    return None

def parse_html_file(file_path: Path) -> Dict[str, Dict[str, Any]]:
    """Parse HTML file and extract data for each item code."""
    data = {}

    try:
        content = file_path.read_text(encoding='utf-8')
    except Exception:
        return data

    # Find all article elements (each sheet)
    article_pattern = r'<article[^>]*class="sheet"[^>]*>.*?</article>'
    articles = re.findall(article_pattern, content, re.DOTALL)

    for article in articles:
        # Extract item code
        item_match = re.search(r'<strong>([^<]+)</strong>', article)
        if not item_match:
            continue

        item_code = item_match.group(1).strip()

        # Extract all field-value pairs
        fields = {}
        rows = re.findall(r'<tr>.*?</tr>', article, re.DOTALL)

        for row in rows:
            th_match = re.search(r'<th[^>]*>([^<]+)</th>', row)
            td_match = re.search(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)

            if th_match and td_match:
                field_name = th_match.group(1).strip()
                td_content = td_match.group(1).strip()

                # Remove any HTML tags from td_content
                td_content = re.sub(r'<[^>]+>', '', td_content)

                # Check if it's void/blank
                if "left blank" in td_content.lower():
                    fields[field_name] = None
                else:
                    fields[field_name] = td_content

        data[item_code] = fields

    return data

def extract_calibration_date(data: Dict[str, Dict[str, Any]], item_code: str) -> Tuple[Optional[str], str]:
    """Extract calibration date for an item from calibration_log."""
    if item_code not in data:
        return None, "calibration_log"

    fields = data[item_code]
    for field_name, value in fields.items():
        if "frame last calibrated" in field_name.lower():
            if value is None:
                return None, "calibration_log"
            date = parse_date(value)
            return date, "calibration_log"

    return None, "calibration_log"

def extract_test_date(data_test: Dict[str, Dict[str, Any]], 
                     data_lab: Dict[str, Dict[str, Any]], 
                     item_code: str) -> Tuple[Optional[str], str]:
    """Extract test date from test_reports, fallback to lab_certificates."""
    # Try test_reports first
    if item_code in data_test:
        fields = data_test[item_code]
        for field_name, value in fields.items():
            if "break test performed" in field_name.lower():
                if value is not None:
                    date = parse_date(value)
                    if date:
                        return date, "test_reports"

    # Fallback to lab_certificates
    if item_code in data_lab:
        fields = data_lab[item_code]
        for field_name, value in fields.items():
            if "laboratory test performed" in field_name.lower():
                if value is not None:
                    date = parse_date(value)
                    if date:
                        return date, "lab_certificates"

    return None, "test_reports"

def extract_measured_load(data_lab: Dict[str, Dict[str, Any]], 
                         data_test: Dict[str, Dict[str, Any]], 
                         item_code: str) -> Tuple[Optional[str], str]:
    """Extract measured load from lab_certificates, fallback to test_reports."""
    # Try lab_certificates first
    if item_code in data_lab:
        fields = data_lab[item_code]
        for field_name, value in fields.items():
            if "load at failure (lab certified)" in field_name.lower():
                if value is not None:
                    load = parse_load(value)
                    if load:
                        return load, "lab_certificates"

    # Fallback to test_reports
    if item_code in data_test:
        fields = data_test[item_code]
        for field_name, value in fields.items():
            if "load at failure (in-house)" in field_name.lower():
                if value is not None:
                    load = parse_load(value)
                    if load:
                        return load, "test_reports"

    return None, "lab_certificates"

def extract_specified_minimum(data_spec: Dict[str, Dict[str, Any]], item_code: str) -> Tuple[Optional[str], str]:
    """Extract specified minimum from spec_sheets."""
    if item_code not in data_spec:
        return None, "spec_sheets"

    fields = data_spec[item_code]
    for field_name, value in fields.items():
        if "drawing minimum at failure" in field_name.lower():
            if value is None:
                return None, "spec_sheets"
            load = parse_load(value)
            return load, "spec_sheets"

    return None, "spec_sheets"

def handle_conflict(values: List[Tuple[Optional[str], str]]) -> Any:
    """Handle conflicting values from the same document."""
    if not values:
        return "ABSENT"

    # Check if all values are the same
    unique_values = {v[0] for v in values if v[0] is not None}
    unique_docs = {v[1] for v in values}

    if len(unique_docs) > 1:
        # Values from different documents - take the first non-None
        for value, doc in values:
            if value is not None:
                return [value, doc]
        return "ABSENT"

    # All from same document
    if len(unique_values) == 0:
        return "ABSENT"
    elif len(unique_values) == 1:
        return [list(unique_values)[0], values[0][1]]
    else:
        return "CONFLICT"

def main(directory_path: str):
