    data = []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find all INSERT statements
    insert_pattern = r'INSERT INTO \w+ \([^)]+\) VALUES\s*\(([^)]+)\);'
    # Handle multi-line VALUES
    content = content.replace('\n', ' ')
    matches = re.findall(insert_pattern, content)

    for match in matches:
        # Parse values - handle NULL and numeric values
        values = []
        current = ''
        in_quotes = False
        for char in match:
            if char == "'" and not in_quotes:
                in_quotes = True
                current += char
            elif char == "'" and in_quotes:
                in_quotes = False
                current += char
            elif char == ',' and not in_quotes:
                values.append(current.strip())
                current = ''
            else:
                current += char
        if current:
            values.append(current.strip())

        # Clean values
        cleaned_values = []
        for v in values:
            if v.upper() == 'NULL':
                cleaned_values.append(None)
            elif v.startswith("'") and v.endswith("'"):
                cleaned_values.append(v[1:-1])
            else:
                # Try to parse as int or float
                try:
                    if '.' in v:
                        cleaned_values.append(float(v))
                    else:
                        cleaned_values.append(int(v))
                except:
                    cleaned_values.append(v)

        data.append(cleaned_values)

    return data

def extract_column_names(file_path):
    """Extract column names from CREATE TABLE statement."""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find CREATE TABLE statement
    create_match = re.search(r'CREATE TABLE (\w+) \(([^)]+)\)', content, re.DOTALL)
    if not create_match:
        return []

    columns_section = create_match.group(2)
    columns = []
    for line in columns_section.split(','):
        line = line.strip()
        if line:
            # Extract column name (first word before any spaces or parentheses)
            col_name = line.split()[0]
            columns.append(col_name)

    return columns

