    """Load data from a document file."""
    file_path = os.path.join(directory, f"{doc_name}.sql")
    if not os.path.exists(file_path):
        return []

    columns = extract_column_names(file_path)
    rows = parse_sql_file(file_path)

    # Convert rows to dictionaries
    data = []
    for row in rows:
        if len(row) != len(columns):
