    matches = re.findall(insert_pattern, content, re.DOTALL | re.IGNORECASE)

    for match in matches:
        columns_str, values_str = match
        columns = [col.strip() for col in columns_str.split(',')]

        # Handle multi-row VALUES
        values_groups = re.findall(r'\((.*?)\)', values_str)
        for values in values_groups:
            # Parse values, handling NULL and numeric values
            raw_values = []
            current = ''
            in_quotes = False
            for char in values:
                if char == "'" and not in_quotes:
