        file_path = Path(directory) / filename
        if not file_path.exists():
            continue

        data = parse_sql_file(file_path)

        # Group by cmp_code
        grouped = {}
        for row in data:
            cmp_code = row.get('cmp_code')
            if cmp_code not in grouped:
                grouped[cmp_code] = []
            grouped[cmp_code].append(row)

        facts[fact_key] = grouped

    return facts

def get_calibration_date(facts, cmp_code):
    """Get calibration date from calibration_log."""
    cal_data = facts['calibration_log'].get(cmp_code, [])
    if not cal_data:
        return None

    # Get the rig_cal_epd value
    for row in cal_data:
        if 'rig_cal_epd' in row and row['rig_cal_epd'] is not None:
            return epoch_day_to_date(row['rig_cal_epd'])
    return None

def get_test_date(facts, cmp_code):
    """Get test date from test_reports first, then lab_certificates."""
    # Try test_reports first
    test_data = facts['test_reports'].get(cmp_code, [])
    if test_data:
        # Check for inhouse_break_epd
        for row in test_data:
            if 'inhouse_break_epd' in row and row['inhouse_break_epd'] is not None:
                return epoch_day_to_date(row['inhouse_break_epd'])

    # Try lab_certificates
    lab_data = facts['lab_certificates'].get(cmp_code, [])
    if lab_data:
        for row in lab_data:
            if 'lab_break_epd' in row and row['lab_break_epd'] is not None:
                return epoch_day_to_date(row['lab_break_epd'])

    return None

def get_measured_load(facts, cmp_code):
    """Get measured load from lab_certificates first, then test_reports."""
    # Try lab_certificates first
    lab_data = facts['lab_certificates'].get(cmp_code, [])
    lab_values = []
    if lab_data:
        for row in lab_data:
            if 'lab_break_dan' in row and row['lab_break_dan'] is not None:
                lab_values.append(row['lab_break_dan'])

    if lab_values:
        # Check for conflicts
        if len(set(lab_values)) > 1:
            return 'CONFLICT', 'lab_certificates'
        return dan_to_kn(lab_values[0]), 'lab_certificates'

    # Try test_reports
    test_data = facts['test_reports'].get(cmp_code, [])
    test_values = []
    if test_data:
        for row in test_data:
            if 'inhouse_break_dan' in row and row['inhouse_break_dan'] is not None:
                test_values.append(row['inhouse_break_dan'])

    if test_values:
        # Check for conflicts
        if len(set(test_values)) > 1:
            return 'CONFLICT', 'test_reports'
        return dan_to_kn(test_values[0]), 'test_reports'

    return 'ABSENT', None

def get_specified_minimum(facts, cmp_code):
    """Get specified minimum from spec_sheets."""
    spec_data = facts['spec_sheets'].get(cmp_code, [])
    if not spec_data:
        return 'ABSENT', None

    values = []
    for row in spec_data:
        if 'floor_force_dan' in row and row['floor_force_dan'] is not None:
            values.append(row['floor_force_dan'])

    if not values:
        return 'ABSENT', None

    # Check for conflicts
    if len(set(values)) > 1:
        return 'CONFLICT', 'spec_sheets'

    return dan_to_kn(values[0]), 'spec_sheets'

def process_pair(pair_id, facts):
    """Process a single pair and return its facts."""
    # Parse pair_id to get rule and component
    parts = pair_id.split('::')
    if len(parts) != 2:
        return {}

    rule, cmp_code = parts

    result = {}

    if rule == 'ea.calibration_current':
        # Get calibration date
        cal_date = get_calibration_date(facts, cmp_code)
        if cal_date is None:
            result['calibration date'] = 'ABSENT'
        else:
            result['calibration date'] = [cal_date, 'calibration_log']

        # Get test date
        test_date = get_test_date(facts, cmp_code)
        if test_date is None:
            result['test date'] = 'ABSENT'
        else:
            # Determine source document
            test_data = facts['test_reports'].get(cmp_code, [])
            source = 'test_reports' if test_data and any(
                'inhouse_break_epd' in row and row['inhouse_break_epd'] is not None 
                for row in test_data
            ) else 'lab_certificates'
            result['test date'] = [test_date, source]

    elif rule == 'ea.load_with_margin':
        # Get measured load
        measured_load, measured_source = get_measured_load(facts, cmp_code)
        if measured_load == 'ABSENT':
            result['measured load'] = 'ABSENT'
        elif measured_load == 'CONFLICT':
            result['measured load'] = 'CONFLICT'
        else:
            # Format as decimal string
            result['measured load'] = [f"{measured_load:.2f}", measured_source]

        # Get specified minimum
        spec_min, spec_source = get_specified_minimum(facts, cmp_code)
        if spec_min == 'ABSENT':
            result['specified minimum'] = 'ABSENT'
        elif spec_min == 'CONFLICT':
            result['specified minimum'] = 'CONFLICT'
        else:
            # Format as decimal string
            result['specified minimum'] = [f"{spec_min:.2f}", spec_source]

    return result

def main():
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)

    directory = sys.argv[1]

