def parse_edi_file(file_path: Path) -> Dict[str, List[Dict]]:
    """
    Parse an EDI file and extract records for each part (identified by LIN**BP*).
    Each record is a dictionary of field values.
    """
    records = {}
    current_record = None
    part_id = None

    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue

            # Start of a new record
            if line.startswith('LX'):
                if current_record and part_id:
                    if part_id not in records:
                        records[part_id] = []
                    records[part_id].append(current_record)

                current_record = {}
                part_id = None

            # Part identifier
            elif line.startswith('LIN**BP*'):
                parts = line.split('*')
                if len(parts) >= 4:
                    part_id = parts[3]
                    current_record['part_id'] = part_id

            # Supplier
            elif line.startswith('N1*SU*'):
                parts = line.split('*')
                if len(parts) >= 3:
                    current_record['supplier'] = parts[2]

            # Drawing revision
            elif line.startswith('REF*DR*'):
                parts = line.split('*')
                if len(parts) >= 3:
                    current_record['drawing_revision'] = parts[2]

            # Dates
            elif line.startswith('DTP'):
                parts = line.split('*')
                if len(parts) >= 4:
                    qualifier = parts[1]
                    date_str = parts[3]
                    if len(date_str) == 8:  # CCYYMMDD
                        # Convert to YYYY-MM-DD
                        formatted_date = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
                        current_record[f'date_{qualifier}'] = formatted_date

            # Measurements
            elif line.startswith('MEA*TE*'):
                parts = line.split('*')
                if len(parts) >= 6:
                    qualifier = parts[2]  # UFL, UFH, DUF, UFM
                    value = parts[4]
                    unit = parts[5]
                    current_record[f'measure_{qualifier}'] = {
                        'value': value,
                        'unit': unit
                    }

            # Quality decision
            elif line.startswith('REF*QAD*'):
                parts = line.split('*')
                if len(parts) >= 3:
                    current_record['quality_decision'] = parts[2]

    # Don't forget the last record
    if current_record and part_id:
        if part_id not in records:
            records[part_id] = []
        records[part_id].append(current_record)

    return records

def convert_to_kilonewtons(value_str: str, unit: str) -> str:
    """
    Convert a force value to kilonewtons.
    Returns the value as a decimal string with appropriate precision.
    """
    try:
        value = float(value_str)
        if unit == 'NT':  # Newtons to kilonewtons
            value = value / 1000.0
        elif unit == 'KN':  # Already kilonewtons
            pass
        else:
            # Unknown unit, return as is
            return value_str

        # Format as decimal string without unnecessary trailing zeros
        if value.is_integer():
            return str(int(value))
        else:
            # Keep up to 3 decimal places
            return f"{value:.3f}".rstrip('0').rstrip('.')
    except (ValueError, TypeError):
        return value_str

def extract_fact_value(records: Dict[str, List[Dict]], part_id: str, 
                      fact_name: str, document_name: str) -> Tuple[Optional[str], Optional[str]]:
    """
    Extract a fact value for a specific part from records.
    Returns (value, document) or (None, None) if not found.
    Handles conflicts when multiple records have different values.
    """
    if part_id not in records:
        return None, None

    part_records = records[part_id]
    values = []

    for record in part_records:
        value = None

        if fact_name == 'calibration date':
            # Look for DTP*300 (calibration date)
            if 'date_300' in record:
                value = record['date_300']

        elif fact_name == 'test date':
            # First check test_reports (DTP*301)
            if document_name == 'test_reports' and 'date_301' in record:
                value = record['date_301']
            # Then check lab_certificates (DTP*302)
            elif document_name == 'lab_certificates' and 'date_302' in record:
                value = record['date_302']

        elif fact_name == 'measured load':
            # First check lab_certificates (MEA*TE*UFL)
            if document_name == 'lab_certificates' and 'measure_UFL' in record:
                meas = record['measure_UFL']
                value = convert_to_kilonewtons(meas['value'], meas['unit'])
            # Then check test_reports (MEA*TE*UFH)
            elif document_name == 'test_reports' and 'measure_UFH' in record:
                meas = record['measure_UFH']
                value = convert_to_kilonewtons(meas['value'], meas['unit'])

        elif fact_name == 'specified minimum':
            # Check spec_sheets (MEA*TE*UFM)
            if 'measure_UFM' in record:
                meas = record['measure_UFM']
                value = convert_to_kilonewtons(meas['value'], meas['unit'])

        if value is not None:
            values.append(value)

    if not values:
        return None, None

    # Check for conflicts (different values)
    unique_values = set(values)
    if len(unique_values) > 1:
        return "CONFLICT", document_name

    return list(unique_values)[0], document_name

