import json
import os
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_edi_file(file_path: Path) -> List[Dict]:
    """
    Parse an EDI file and extract records for each LX loop.
    Returns a list of dictionaries, each representing one record (LX loop).
    """
    records = []
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    current_record = {}
    in_lx = False
    for line in lines:
        line = line.strip()
        if not line:
            continue
        segments = line.split('~')
        for seg in segments:
            if not seg:
                continue
            fields = seg.split('*')
            seg_id = fields[0]

            if seg_id == 'LX':
                # Start new record
                if current_record:
                    records.append(current_record)
                current_record = {'LX': fields[1] if len(fields) > 1 else ''}
                in_lx = True
            elif in_lx:
                if seg_id == 'LIN':
                    # LIN**BP*P-40801 format
                    if len(fields) >= 4 and fields[2] == 'BP':
                        current_record['BP'] = fields[3]  # Part number
                elif seg_id == 'N1':
                    if len(fields) >= 3 and fields[1] == 'SU':
                        current_record['SU'] = fields[2]  # Supplier
                elif seg_id == 'REF':
                    if len(fields) >= 3:
                        qual = fields[1]
                        if qual == 'DR':
                            current_record['DR'] = fields[2]  # Drawing revision
                        elif qual == 'ZZ':
                            current_record['ZZ'] = fields[2]  # Source token
                        elif qual == 'QAD':
                            current_record['QAD'] = fields[2]  # Quality decision
                elif seg_id == 'DTP':
                    if len(fields) >= 4:
                        qual = fields[1]
                        date = fields[3]
                        # Convert CCYYMMDD to YYYY-MM-DD
                        if len(date) == 8:
                            date = f"{date[0:4]}-{date[4:6]}-{date[6:8]}"
                        if qual == '300':
                            current_record['CAL_DATE'] = date  # Calibration date
                        elif qual == '301':
                            current_record['TEST_DATE_INHOUSE'] = date  # In-house test date
                        elif qual == '302':
                            current_record['TEST_DATE_LAB'] = date  # Lab test date
                        elif qual == '690':
                            current_record['TEST_BOOKED'] = date  # Test booked date
                        elif qual == '097':
                            current_record['CREATED'] = date  # Created date
                elif seg_id == 'MEA':
                    if len(fields) >= 6:
                        qual1 = fields[1]
                        qual2 = fields[2]
                        qual3 = fields[3]
                        value = fields[4]
                        unit = fields[5]
                        if qual1 == 'TE':
                            if qual2 == 'UFL':
                                current_record['UFL'] = (value, unit)  # Ultimate force lab
                            elif qual2 == 'UFH':
                                current_record['UFH'] = (value, unit)  # Ultimate force in-house
                            elif qual2 == 'DUF':
                                current_record['DUF'] = (value, unit)  # Design ultimate force
                            elif qual2 == 'UFM':
                                current_record['UFM'] = (value, unit)  # Minimum ultimate force

    # Add last record
    if current_record:
        records.append(current_record)

    return records

def convert_to_kN(value_str: str, unit: str) -> str:
    """
    Convert a force value to kN.
    value_str: string representation of the value
    unit: 'KN' for kilonewton, 'NT' for newton
    Returns: string with decimal representation in kN
    """
    try:
        value = float(value_str)
        if unit == 'NT':
            value = value / 1000.0  # Convert newton to kN
        # Format as decimal string without unnecessary trailing zeros
        result = f"{value:.6f}".rstrip('0').rstrip('.')
        return result if result else "0"
    except ValueError:
        return "0"

def extract_facts(records: List[Dict], part_number: str, fact_type: str) -> Dict:
    """
    Extract facts for a specific part number from records.
    Returns a dictionary with all values found for that part.
    """
    facts = {}
    for rec in records:
        if rec.get('BP') == part_number:
            # Collect all relevant fields
            if 'DR' in rec:
                facts['DR'] = rec['DR']
            if 'CAL_DATE' in rec:
                facts['CAL_DATE'] = rec['CAL_DATE']
            if 'TEST_DATE_INHOUSE' in rec:
                facts['TEST_DATE_INHOUSE'] = rec['TEST_DATE_INHOUSE']
            if 'TEST_DATE_LAB' in rec:
                facts['TEST_DATE_LAB'] = rec['TEST_DATE_LAB']
            if 'UFL' in rec:
                value, unit = rec['UFL']
                facts['UFL'] = convert_to_kN(value, unit)
            if 'UFH' in rec:
                value, unit = rec['UFH']
                facts['UFH'] = convert_to_kN(value, unit)
            if 'UFM' in rec:
                value, unit = rec['UFM']
                facts['UFM'] = convert_to_kN(value, unit)
    return facts

def resolve_conflict(values: List[str]) -> Union[str, List[str]]:
    """
    Check if all values in list are the same.
    Returns the value if all agree, "CONFLICT" otherwise.
    """
    if not values:
        return "ABSENT"
    unique = set(values)
    if len(unique) == 1:
        return list(unique)[0]
    return "CONFLICT"

def main(directory: str):
    dir_path = Path(directory)

    # Load all files
    files = {
        'calibration_log': dir_path / 'calibration_log.edi',
        'lab_certificates': dir_path / 'lab_certificates.edi',
        'parts': dir_path / 'parts.edi',
        'spec_sheets': dir_path / 'spec_sheets.edi',
        'test_reports': dir_path / 'test_reports.edi'
    }

    # Parse all files
    records = {}
    for name, path in files.items():
        if path.exists():
            records[name] = parse_edi_file(path)
        else:
            records[name] = []

    # Define pairs based on the problem statement
    pairs = []
    for i in range(1, 17):
        part_num = f"P-408{i:02d}"
