            result[rule_id][part_number] = {
                "calibration date": cal_value,
                "test date": test_value
            }

        elif rule_id == "ea.load_with_margin":
            # Fact: measured load
            lab_facts = extract_facts(records['lab_certificates'], part_number, 'lab')
