import json
import os
import re
import sys
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_date(date_str: str) -> Optional[str]:
    """Parse various date formats to YYYY-MM-DD."""
    if not date_str:
        return None
    # Remove ordinal suffixes (st, nd, rd, th)
    date_str = re.sub(r'(\d)(st|nd|rd|th)', r'\1', date_str)

    # Common patterns in the text
    patterns = [
        r'(\d{1,2})\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})',
        r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{1,2})(?:st|nd|rd|th)?,\s+(\d{4})',
        r'(\d{1,2})/(\d{1,2})/(\d{4})',
        r'(\d{4})-(\d{2})-(\d{2})',
    ]

    for pattern in patterns:
        match = re.search(pattern, date_str, re.IGNORECASE)
        if match:
            try:
                # Try to parse with datetime
                for fmt in ['%d %B %Y', '%B %d, %Y', '%d/%m/%Y', '%Y-%m-%d', '%Y %B %d']:
                    try:
                        dt = datetime.strptime(match.group(0), fmt)
                        return dt.strftime('%Y-%m-%d')
                    except ValueError:
                        continue
            except:
                continue

    # Fallback: look for month-year patterns
    month_map = {
        'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
        'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
    }

    for month_name, month_num in month_map.items():
        if month_name in date_str.lower():
            year_match = re.search(r'(\d{4})', date_str)
            if year_match:
                year = int(year_match.group(1))
                day_match = re.search(r'(\d{1,2})', date_str.split(month_name)[0])
                day = int(day_match.group(1)) if day_match else 1
                try:
                    dt = datetime(year, month_num, day)
                    return dt.strftime('%Y-%m-%d')
                except:
                    continue

    return None

def parse_load(load_str: str) -> Optional[str]:
    """Parse load values, convert to decimal string in kN."""
    if not load_str:
        return None

    # Extract number
    match = re.search(r'(\d+(?:\.\d+)?)\s*(?:kN|kilonewtons?)', load_str, re.IGNORECASE)
    if match:
        return match.group(1)

    # Try just a number
    match = re.search(r'(\d+(?:\.\d+)?)', load_str)
    if match:
        return match.group(1)

    return None

def parse_calibration_log(content: str) -> Dict[str, str]:
    """Parse calibration_log.txt for calibration dates."""
    results = {}

    # Split by message separator
    messages = content.split('========================================================================')

    for msg in messages:
        if not msg.strip():
            continue

        # Extract part number
        part_match = re.search(r'P-(\d{5})', msg)
        if not part_match:
            continue

        part_id = f"P-{part_match.group(1)}"

        # Look for calibration date
        date_patterns = [
            r'calibrated on\s+([^\.]+)',
            r'calibration sticker says\s+([^\.]+)',
            r'calibration day[^\.]*\.',  # For "I can't find" cases
        ]

        date_found = None
        for pattern in date_patterns:
            match = re.search(pattern, msg, re.IGNORECASE)
            if match:
                if "can't find" in match.group(0).lower():
                    # No date available
                    date_found = None
                    break
                date_str = match.group(1)
                date_found = parse_date(date_str)
                if date_found:
                    break

        if date_found:
            results[part_id] = date_found
        elif "can't find" not in msg.lower():
            # If we parsed the message but found no date, and it's not a "can't find" case
            # Try to extract any date from the message
            all_dates = re.findall(r'\b(\d{1,2}(?:st|nd|rd|th)?\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{4})\b', msg, re.IGNORECASE)
            if all_dates:
                results[part_id] = parse_date(all_dates[0])

    return results

def parse_test_reports(content: str) -> Dict[str, Dict[str, str]]:
    """Parse test_reports.txt for test dates and measured loads."""
    results = {}

    messages = content.split('========================================================================')

    for msg in messages:
        if not msg.strip():
            continue

        part_match = re.search(r'P-(\d{5})', msg)
        if not part_match:
            continue

        part_id = f"P-{part_match.group(1)}"

        # Extract test date
        test_date = None
        date_patterns = [
            r'(?:ran on|broke it on|tested on)\s+([^\.]+)',
            r'on\s+(\d{1,2}(?:st|nd|rd|th)?\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[^\.]+)',
        ]

        for pattern in date_patterns:
            match = re.search(pattern, msg, re.IGNORECASE)
            if match:
                test_date = parse_date(match.group(1))
                if test_date:
                    break

        # Extract measured load
        measured_load = None
        load_patterns = [
            r'let go at\s+([^\.]+)',
            r'recorded failure at\s+([^\.]+)',
            r'failed at\s+([^\.]+)',
        ]

        for pattern in load_patterns:
            match = re.search(pattern, msg, re.IGNORECASE)
            if match:
                measured_load = parse_load(match.group(1))
                if measured_load:
                    break

        results[part_id] = {
            'test_date': test_date,
            'measured_load': measured_load
        }

    return results

def parse_lab_certificates(content: str) -> Dict[str, Dict[str, str]]:
    """Parse lab_certificates.txt for test dates and certified loads."""
    results = {}

    messages = content.split('========================================================================')

    for msg in messages:
        if not msg.strip():
            continue

        part_match = re.search(r'P-(\d{5})', msg)
        if not part_match:
            continue

        part_id = f"P-{part_match.group(1)}"

        # Extract test date
        test_date = None
        date_patterns = [
            r'(?:ran it on|test happened on)\s+([^\.]+)',
            r'on\s+(\d{1,2}(?:st|nd|rd|th)?\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[^\.]+)',
        ]

        for pattern in date_patterns:
            match = re.search(pattern, msg, re.IGNORECASE)
            if match:
                test_date = parse_date(match.group(1))
                if test_date:
                    break

        # Extract certified load
        certified_load = None
        load_patterns = [
            r'failed at\s+([^\.]+)',
            r'failure at\s+([^\.]+)',
            r'certifies failure at\s+([^\.]+)',
        ]

        for pattern in load_patterns:
            match = re.search(pattern, msg, re.IGNORECASE)
            if match:
                certified_load = parse_load(match.group(1))
                if certified_load:
                    break

        # Check for empty failure load
        if "leaves the failure load empty" in msg.lower():
            certified_load = None

        results[part_id] = {
            'test_date': test_date,
            'certified_load': certified_load
        }

    return results

def parse_spec_sheets(content: str) -> Dict[str, str]:
    """Parse spec_sheets.txt for specified minimum loads."""
    results = {}

    messages = content.split('========================================================================')

    for msg in messages:
        if not msg.strip():
            continue

        part_match = re.search(r'P-(\d{5})', msg)
        if not part_match:
            continue

        part_id = f"P-{part_match.group(1)}"

        # Check for "no minimum" case
        if "gives no minimum" in msg.lower() or "no minimum" in msg.lower():
            results[part_id] = None
            continue

        # Extract minimum load
        min_load = None
        load_patterns = [
            r'at least\s+([^\.]+)',
            r'minimum at failure is\s+([^\.]+)',
            r'calls for\s+([^\.]+)',
        ]

        for pattern in load_patterns:
            match = re.search(pattern, msg, re.IGNORECASE)
            if match:
                min_load = parse_load(match.group(1))
                if min_load:
                    break

        results[part_id] = min_load

    return results

def read_file(filepath: Path) -> str:
    """Read file content."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            return f.read()
    except:
        return ""

def main(directory: str):
    # Parse all files
    base_path = Path(directory)

    calibration_data = parse_calibration_log(read_file(base_path / "calibration_log.txt"))
    test_reports_data = parse_test_reports(read_file(base_path / "test_reports.txt"))
    lab_certificates_data = parse_lab_certificates(read_file(base_path / "lab_certificates.txt"))
    spec_sheets_data = parse_spec_sheets(read_file(base_path / "spec_sheets.txt"))

    # All part IDs from the pairs
    all_parts = [f"P-{str(i).zfill(5)}" for i in range(1, 17)]

    result = {}

    # Process ea.calibration_current pairs
    for part_id in all_parts:
        pair_id = f"ea.calibration_current::{part_id}"
        pair_result = {}

        # Fact: calibration date
        cal_date = calibration_data.get(part_id)
        if cal_date:
            pair_result['calibration date'] = [cal_date, "calibration_log"]
        else:
            pair_result['calibration date'] = "ABSENT"

        # Fact: test date
        test_date = None
        source_doc = None

        # First check test_reports
        test_report = test_reports_data.get(part_id)
        if test_report and test_report.get('test_date'):
            test_date = test_report['test_date']
            source_doc = "test_reports"
        else:
            # Fallback to lab_certificates
            lab_cert = lab_certificates_data.get(part_id)
            if lab_cert and lab_cert.get('test_date'):
                test_date = lab_cert['test_date']
                source_doc = "lab_certificates"

        if test_date:
            pair_result['test date'] = [test_date, source_doc]
        else:
            pair_result['test date'] = "ABSENT"

        result[pair_id] = pair_result

    # Process ea.load_with_margin pairs
    for part_id in all_parts:
        pair_id = f"ea.load_with_margin::{part_id}"
        pair_result = {}

        # Fact: measured load
        measured_load = None
        source_doc = None

        # First check lab_certificates
        lab_cert = lab_certificates_data.get(part_id)
        if lab_cert and lab_cert.get('certified_load'):
            measured_load = lab_cert['certified_load']
            source_doc = "lab_certificates"
        else:
            # Fallback to test_reports
            test_report = test_reports_data.get(part_id)
            if test_report and test_report.get('measured_load'):
                measured_load = test_report['measured_load']
                source_doc = "test_reports"

        if measured_load:
            pair_result['measured load'] = [measured_load, source_doc]
        else:
            pair_result['measured load'] = "ABSENT"

        # Fact: specified minimum
        spec_min = spec_sheets_data.get(part_id)
        if spec_min is not None:  # Could be None meaning "no minimum"
            pair_result['specified minimum'] = [spec_min, "spec_sheets"] if spec_min else "ABSENT"
        else:
            # Check if part exists in spec_sheets but value wasn't parsed
            spec_content = read_file(base_path / "spec_sheets.txt")
            if part_id in spec_content:
                # Try to parse directly
                for msg in spec_content.split('========================================================================'):
                    if part_id in msg:
                        # Check for conflict
                        matches = re.findall(rf'{part_id}.*?{part_id}', msg, re.DOTALL)
                        if len(matches) > 1:
                            # Multiple entries for same part
                            pair_result['specified minimum'] = "CONFLICT"
                            break

                        # Extract load
                        load_match = re.search(r'(\d+(?:\.\d+)?)\s*(?:kN|kilonewtons?)', msg, re.IGNORECASE)
                        if load_match:
                            pair_result['specified minimum'] = [load_match.group(1), "spec_sheets"]
                        else:
                            pair_result['specified minimum'] = "ABSENT"
                        break
                else:
                    pair_result['specified minimum'] = "ABSENT"
            else:
                pair_result['specified minimum'] = "ABSENT"

        result[pair_id] = pair_result

    # Check for conflicts in spec_sheets (multiple entries for same part)
    spec_content = read_file(base_path / "spec_sheets.txt")
    for part_id in all_parts:
        # Count occurrences of this part in spec_sheets
        occurrences = []
        messages = spec_content.split('========================================================================')
        for msg in messages:
            if part_id in msg and "P-" in msg:
                # Extract load value from this message
                load_match = re.search(r'(\d+(?:\.\d+)?)\s*(?:kN|kilonewtons?)', msg, re.IGNORECASE)
                if load_match:
                    occurrences.append(load_match.group(1))

        if len(occurrences) > 1:
            # Check if all values are the same
            if len(set(occurrences)) > 1:
                pair_id = f"ea.load_with_margin::{part_id}"
                if pair_id in result:
                    result[pair_id]['specified minimum'] = "CONFLICT"

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python program.py <directory_path>")
        sys.exit(1)

    main(sys.argv[1])
