import json
import os
import sys
from pathlib import Path
from datetime import datetime, timedelta
import re

def parse_iso_week_date(date_str):
    """Parse ISO week date YYYY-Www-D to datetime.date."""
    if date_str == "~":
        return None
    # Format: YYYY-Www-D
    match = re.match(r"(\d{4})-W(\d{2})-(\d)", date_str)
    if not match:
        raise ValueError(f"Invalid ISO week date: {date_str}")
    year, week, day = map(int, match.groups())
    # First Thursday of year is in week 1
    # Calculate using: first day of year + (week-1)*7 + (day-1) - weekday offset
    jan1 = datetime(year, 1, 1).date()
    # Weekday where Monday=0
    jan1_weekday = jan1.weekday()  # Monday=0
    # If Jan 1 is Friday/Saturday/Sunday, it belongs to previous year's last week
    # For ISO week: Monday is day 1
    # Find the Monday of week 1
    if jan1_weekday <= 3:  # Jan1 is Mon-Thu
        week_start = jan1 - timedelta(days=jan1_weekday)
    else:  # Jan1 is Fri-Sun
        week_start = jan1 + timedelta(days=(7 - jan1_weekday))
    # Add weeks and days
    target_date = week_start + timedelta(weeks=week-1, days=day-1)
    return target_date

def read_tsv_file(file_path):
    """Read a TSV file with the given cross-tab format.
    Returns dict: {component.key: {attribute: value}}"""
    data = {}
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = [line.rstrip('\n') for line in f]

    # Skip header lines starting with #
    data_lines = []
    for line in lines:
        if line.startswith('#'):
            continue
        data_lines.append(line)

    if not data_lines:
        return data

    headers = data_lines[0].split('\t')
    # First column is 'attribute'
    # Each subsequent column is a record
    record_ids = headers[1:]

    # Build mapping from record_id to component.key
    comp_key_map = {}
    attribute_rows = []

    for row in data_lines[1:]:
        parts = row.split('\t')
        if len(parts) < len(headers):
            continue
        attr_name = parts[0]
        values = parts[1:]

        if attr_name == 'component.key':
            for rec_id, comp_key in zip(record_ids, values):
                comp_key_map[rec_id] = comp_key
        else:
            attribute_rows.append((attr_name, values))

    # Now organize by component.key
    for rec_id, comp_key in comp_key_map.items():
        if comp_key not in data:
            data[comp_key] = {}

        for attr_name, values in attribute_rows:
            idx = record_ids.index(rec_id)
            if idx < len(values):
                val = values[idx]
                if val != '~':
                    data[comp_key][attr_name] = val

    return data

def get_calibration_date(data, component_key):
    """Get calibration date from calibration_log for a component."""
    if component_key not in data.get('calibration_log', {}):
        return None, None

    comp_data = data['calibration_log'][component_key]
    if 'rig.cal.wk' in comp_data:
        date_str = comp_data['rig.cal.wk']
        try:
            date_obj = parse_iso_week_date(date_str)
            return date_obj, 'calibration_log'
        except ValueError:
            return None, None
    return None, None

def get_test_date(data, component_key):
    """Get test date according to rules: test_reports first, then lab_certificates."""
    # Try test_reports first
    if component_key in data.get('test_reports', {}):
        comp_data = data['test_reports'][component_key]
        if 'inhouse.break.wk' in comp_data:
            date_str = comp_data['inhouse.break.wk']
            if date_str != '~':
                try:
                    date_obj = parse_iso_week_date(date_str)
                    return date_obj, 'test_reports'
                except ValueError:
                    pass

    # Fallback to lab_certificates
    if component_key in data.get('lab_certificates', {}):
        comp_data = data['lab_certificates'][component_key]
        if 'lab.break.wk' in comp_data:
            date_str = comp_data['lab.break.wk']
            if date_str != '~':
                try:
                    date_obj = parse_iso_week_date(date_str)
                    return date_obj, 'lab_certificates'
                except ValueError:
                    pass

    return None, None

def get_measured_load(data, component_key):
    """Get measured load according to rules: lab_certificates first, then test_reports."""
    # Try lab_certificates first
    if component_key in data.get('lab_certificates', {}):
        comp_data = data['lab_certificates'][component_key]
        if 'lab.break.kn' in comp_data:
            load_str = comp_data['lab.break.kn']
            if load_str != '~':
                try:
                    load_val = float(load_str)
                    return load_val, 'lab_certificates'
                except ValueError:
                    pass

    # Fallback to test_reports
    if component_key in data.get('test_reports', {}):
        comp_data = data['test_reports'][component_key]
        if 'inhouse.break.kn' in comp_data:
            load_str = comp_data['inhouse.break.kn']
            if load_str != '~':
                try:
                    load_val = float(load_str)
                    return load_val, 'test_reports'
                except ValueError:
                    pass

    return None, None

def get_specified_minimum(data, component_key):
    """Get specified minimum from spec_sheets."""
    if component_key in data.get('spec_sheets', {}):
        comp_data = data['spec_sheets'][component_key]
        if 'floor.force.kn' in comp_data:
            load_str = comp_data['floor.force.kn']
            if load_str != '~':
                try:
                    load_val = float(load_str)
                    return load_val, 'spec_sheets'
                except ValueError:
                    pass
    return None, None

def check_conflict(data, component_key, fact_name):
    """Check for conflicting values in the deciding document(s)."""
    if fact_name == 'calibration date':
        # Only calibration_log establishes it
        if component_key in data.get('calibration_log', {}):
            comp_data = data['calibration_log'][component_key]
            values = []
            for rec_id, rec_data in data['calibration_log'].items():
                if rec_data.get('component.key') == component_key:
