def parse_iso_week_date(date_str: str) -> datetime:
    """Parse ISO week date format YYYY-Www-D to datetime."""
    if date_str == "~":
        raise ValueError("Missing date")
    year, week_day = date_str.split("-W")
    week, weekday = week_day.split("-")
    # Using ISO week date: first day of week is Monday, weekday 1-7
    # Construct date from ISO week date
    # Simplified: using strptime with %G-W%V-%u (requires Python 3.6+)
    return datetime.strptime(date_str + "-1", "%G-W%V-%u-%w")

def read_tsv_file(filepath: Path) -> Dict[str, Dict[str, str]]:
    """Read TSV file and return dict mapping component.key to dict of attributes."""
    data = {}
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = [line.rstrip('\n') for line in f if not line.startswith('#') and line.strip()]

    if not lines:
        return data

    headers = lines[0].split('\t')
    # Find component.key column index
    try:
        key_idx = headers.index("component.key")
    except ValueError:
        # Some files might have attribute as first column
        if headers[0] == "attribute":
            # Transposed format: each column is a record
            return read_transposed_tsv(filepath)
        else:
            raise ValueError(f"component.key not found in {filepath}")

    # Normal row-oriented format
    for line in lines[1:]:
        parts = line.split('\t')
        if len(parts) <= key_idx:
            continue
        component_key = parts[key_idx]
        if component_key == "~" or not component_key:
            continue

        record = {}
        for i, header in enumerate(headers):
            if i >= len(parts):
                continue
            if header != "component.key" and parts[i] != "~":
                record[header] = parts[i]
        data[component_key] = record

    return data

def read_transposed_tsv(filepath: Path) -> Dict[str, Dict[str, str]]:
    """Read transposed TSV where columns are records and rows are attributes."""
    data = {}
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = [line.rstrip('\n') for line in f if not line.startswith('#') and line.strip()]

    if not lines:
        return data

    headers = lines[0].split('\t')
    # First column is "attribute", rest are rec.01, rec.02, etc.
    attribute_idx = {headers[i]: i for i in range(len(headers))}

    # Build mapping from record column to component key
    component_keys = {}
    for line in lines[1:]:
        parts = line.split('\t')
        if parts[0] == "component.key":
            for i in range(1, len(parts)):
                if i < len(headers) and parts[i] != "~":
                    component_keys[headers[i]] = parts[i]
            break

    # Now collect all attributes for each component
    for rec_col, component_key in component_keys.items():
        if component_key not in data:
            data[component_key] = {}

    for line in lines[1:]:
        parts = line.split('\t')
        attribute_name = parts[0]
        if attribute_name == "component.key":
            continue

        for i in range(1, len(parts)):
            if i >= len(headers):
                continue
            rec_col = headers[i]
            if rec_col in component_keys:
                component_key = component_keys[rec_col]
                if parts[i] != "~":
                    data[component_key][attribute_name] = parts[i]

    return data

def get_calibration_date(component_key: str, calibration_log: Dict) -> Tuple[Optional[str], str]:
    """Get calibration date from calibration_log."""
    if component_key not in calibration_log:
        return None, "calibration_log"

