                parse_iso_week_date(value)
                return value, "calibration_log"
            except (ValueError, KeyError):
                continue

    # Check for any date attribute
    for attr_name, value in record.items():
        if "wk" in attr_name.lower() and value != "~":
            try:
                parse_iso_week_date(value)
                return value, "calibration_log"
            except (ValueError, KeyError):
                continue

