            except (ValueError, KeyError):
                continue

    return None, "spec_sheets"

def check_conflict(component_key: str, document_data: Dict, attribute_patterns: List[str]) -> bool:
    """Check if there are conflicting values for the same attribute pattern."""
    if component_key not in document_data:
        return False

    record = document_data[component_key]
    values = {}

    for attr_name, value in record.items():
        for pattern in attribute_patterns:
            if pattern in attr_name.lower() and value != "~":
                if pattern in values:
                    if values[pattern] != value:
                        return True
                else:
                    values[pattern] = value

    return False

