import json
import os
import sys
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Any

def parse_date(date_str: str) -> Optional[datetime]:
    """Parse MM/DD/YYYY date string to datetime object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%m/%d/%Y")
    except ValueError:
        return None

def convert_to_kN(value: str, unit: str) -> Optional[str]:
    """Convert force value to kN as decimal string."""
    if not value or not unit:
        return None
    try:
        val = float(value.strip())
        if unit.strip().upper() == "KN":
            return f"{val:.3f}".rstrip('0').rstrip('.')
        elif unit.strip().upper() == "N":
            return f"{val / 1000:.3f}".rstrip('0').rstrip('.')
        else:
            return None
    except (ValueError, TypeError):
        return None

def read_tsv_file(filepath: Path) -> List[Dict[str, str]]:
    """Read a TSV-like file with '|' delimiter and # comments."""
    data = []
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Find header (first non-comment line)
    header = None
    for line in lines:
        if not line.startswith('#'):
            header = line.strip().split('|')
            break

    if not header:
        return data

    # Process data lines
    for line in lines:
        if line.startswith('#') or line.strip() == '':
            continue
        if line.strip().split('|') == header:
            continue  # Skip header line itself

        parts = line.strip().split('|')
        if len(parts) != len(header):
            continue

        record = {header[i]: parts[i] for i in range(len(header))}
        data.append(record)

    return data

def find_records_for_component(data: List[Dict[str, str]], component_key: str) -> List[Dict[str, str]]:
    """Find all records for a specific component catalog key."""
    return [record for record in data if record.get('COMPONENT_CATALOG_KEY') == component_key]

def get_calibration_date(calibration_data: List[Dict[str, str]], component_key: str) -> Tuple[Optional[str], Optional[str]]:
    """Get calibration date from calibration_log for a component."""
    records = find_records_for_component(calibration_data, component_key)
    if not records:
        return None, None

    # Take the first record (all should have same calibration date if multiple)
    record = records[0]
    date_str = record.get('LOAD_FRAME_CAL_DAY')
    doc_serial = record.get('DOCUMENT_SERIAL')

    if not date_str or date_str.strip() == "":
        return None, None

    return date_str.strip(), doc_serial

def get_test_date(test_reports_data: List[Dict[str, str]], lab_certificates_data: List[Dict[str, str]], component_key: str) -> Tuple[Optional[str], Optional[str]]:
    """Get test date from test_reports first, then lab_certificates as fallback."""
    # Try test_reports first
    test_records = find_records_for_component(test_reports_data, component_key)
    if test_records:
        for record in test_records:
            date_str = record.get('INTERNAL_TRIAL_DAY')
            if date_str and date_str.strip() != "":
                return date_str.strip(), record.get('DOCUMENT_SERIAL')

    # Fallback to lab_certificates
    lab_records = find_records_for_component(lab_certificates_data, component_key)
    if lab_records:
        for record in lab_records:
            date_str = record.get('ACCREDITED_TRIAL_DAY')
            if date_str and date_str.strip() != "":
                return date_str.strip(), record.get('DOCUMENT_SERIAL')

    return None, None

def get_measured_load(lab_certificates_data: List[Dict[str, str]], test_reports_data: List[Dict[str, str]], component_key: str) -> Tuple[Optional[str], Optional[str]]:
    """Get measured load from lab_certificates first, then test_reports as fallback, in kN."""
    # Try lab_certificates first
    lab_records = find_records_for_component(lab_certificates_data, component_key)
    if lab_records:
        for record in lab_records:
            force = record.get('ACCREDITED_ULTIMATE_FORCE')
            unit = record.get('ACCREDITED_ULTIMATE_FORCE_UOM')
            if force and force.strip() != "" and unit and unit.strip() != "":
                kN_value = convert_to_kN(force, unit)
                if kN_value:
                    return kN_value, record.get('DOCUMENT_SERIAL')

    # Fallback to test_reports
    test_records = find_records_for_component(test_reports_data, component_key)
    if test_records:
        for record in test_records:
            force = record.get('INTERNAL_ULTIMATE_FORCE')
            unit = record.get('INTERNAL_ULTIMATE_FORCE_UOM')
            if force and force.strip() != "" and unit and unit.strip() != "":
                kN_value = convert_to_kN(force, unit)
                if kN_value:
                    return kN_value, record.get('DOCUMENT_SERIAL')

    return None, None

def get_specified_minimum(spec_sheets_data: List[Dict[str, str]], component_key: str) -> Tuple[Optional[str], Optional[str]]:
    """Get specified minimum from spec_sheets, in kN."""
    records = find_records_for_component(spec_sheets_data, component_key)
    if not records:
        return None, None

    # Check for conflicts
    values = {}
    for record in records:
        force = record.get('REQUIRED_ULTIMATE_FORCE')
        unit = record.get('REQUIRED_ULTIMATE_FORCE_UOM')
        if force and force.strip() != "" and unit and unit.strip() != "":
            kN_value = convert_to_kN(force, unit)
            if kN_value:
                doc = record.get('DOCUMENT_SERIAL')
                if kN_value not in values:
                    values[kN_value] = doc

    if len(values) == 0:
        return None, None
    elif len(values) == 1:
        kN_value, doc = list(values.items())[0]
        return kN_value, doc
    else:
        # Conflict - multiple different values
        return "CONFLICT", None

def process_calibration_current(component_key: str, calibration_data: List[Dict[str, str]], 
                               test_reports_data: List[Dict[str, str]], lab_certificates_data: List[Dict[str, str]]) -> Dict[str, Any]:
    """Process ea.calibration_current rule for a component."""
    result = {}

    # Get calibration date
    cal_date_str, cal_doc = get_calibration_date(calibration_data, component_key)
    if cal_date_str is None:
        result["calibration date"] = "ABSENT"
    else:
        result["calibration date"] = [cal_date_str, cal_doc]

    # Get test date
    test_date_str, test_doc = get_test_date(test_reports_data, lab_certificates_data, component_key)
    if test_date_str is None:
        result["test date"] = "ABSENT"
    else:
        result["test date"] = [test_date_str, test_doc]

    return result

def process_load_with_margin(component_key: str, lab_certificates_data: List[Dict[str, str]], 
                            test_reports_data: List[Dict[str, str]], spec_sheets_data: List[Dict[str, str]]) -> Dict[str, Any]:
    """Process ea.load_with_margin rule for a component."""
    result = {}

    # Get measured load
    measured_load, measured_doc = get_measured_load(lab_certificates_data, test_reports_data, component_key)
    if measured_load is None:
        result["measured load"] = "ABSENT"
    else:
        result["measured load"] = [measured_load, measured_doc]

    # Get specified minimum
    spec_min, spec_doc = get_specified_minimum(spec_sheets_data, component_key)
    if spec_min is None:
        result["specified minimum"] = "ABSENT"
    elif spec_min == "CONFLICT":
        result["specified minimum"] = "CONFLICT"
    else:
        result["specified minimum"] = [spec_min, spec_doc]

    return result

def main(directory_path: str):
    """Main function to process all files and generate JSON output."""
    base_path = Path(directory_path)

    # Read all data files
    calibration_data = read_tsv_file(base_path / "calibration_log.txt")
    lab_certificates_data = read_tsv_file(base_path / "lab_certificates.txt")
    parts_data = read_tsv_file(base_path / "parts.txt")  # Not used in rules but read for completeness
    spec_sheets_data = read_tsv_file(base_path / "spec_sheets.txt")
    test_reports_data = read_tsv_file(base_path / "test_reports.txt")

    # All component keys from P-41001 to P-41016
    component_keys = [f"P-410{i:02d}" for i in range(1, 17)]

    result = {}

    # Process each pair
    for component_key in component_keys:
        # ea.calibration_current pairs
        pair_id = f"ea.calibration_current::{component_key}"
        result[pair_id] = process_calibration_current(
            component_key, calibration_data, test_reports_data, lab_certificates_data
        )

        # ea.load_with_margin pairs
        pair_id = f"ea.load_with_margin::{component_key}"
        result[pair_id] = process_load_with_margin(
            component_key, lab_certificates_data, test_reports_data, spec_sheets_data
        )

    # Output JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <directory_path>")
        sys.exit(1)

    main(sys.argv[1])
